```c++
template <typename T, size_t N>
constexpr T factorial(size_t n) {
  if constexpr (n == 0) {
    return 1;
  } else {
    return n * factorial<T, N>(n - 1);
  }
}

int main() {
  constexpr int result = factorial<int, 10>(5); //Compile-time computation
  std::cout << result << std::endl; //Prints 120 at runtime, but the calculation happened at compile time
  return 0;
}
