code_example:
template <typename T, size_t N>
constexpr T factorial(size_t n) {
  if constexpr (n == 0) {
    return 1;
  } else {
    return n * factorial<T, N>(n - 1);
  }
}

template<size_t N> 
constexpr std::array<int, N> fib_sequence(){
  std::array<int, N> fib; 
  fib[0] = 0;
  if constexpr (N > 1) fib[1] = 1;
  if constexpr (N > 2){
    for(size_t i = 2; i < N; ++i){
      fib[i] = fib[i-1] + fib[i-2];
    }
  }
  return fib; 
}

int main() {
  constexpr int fact_5 = factorial<int, 10>(5);
  std::cout << "Factorial of 5: " << fact_5 << std::endl;
  constexpr auto fib8 = fib_sequence<8>();
  for(int val : fib8) std::cout << val << " ";
  std::cout << std::endl;
  return 0;
}
